-- PaiFlow公开配置目录：MySQL8未执行增量草案，不创建数据库、不执行原schema。
-- 只迁经审查的公开白名单种子；秘密/环境配置无列外通道，不保存在本表。
-- 原9字段、is_valid筛选及动态更新后读取保留；本模块没有HTTP写接口。
CREATE TABLE IF NOT EXISTS paiflow_public_config (
  id BIGINT NOT NULL AUTO_INCREMENT,
  category VARCHAR(64) NOT NULL,
  code VARCHAR(128) NOT NULL,
  name VARCHAR(255) NULL,
  value TEXT NULL,
  is_valid TINYINT NULL,
  remarks VARCHAR(1000) NULL,
  create_time DATETIME NULL DEFAULT '2000-01-01 00:00:00',
  update_time DATETIME NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_paiflow_public_config_lookup (category,code,is_valid),
  CONSTRAINT ck_paiflow_public_config_valid CHECK (is_valid IS NULL OR is_valid IN (0,1)),
  CONSTRAINT ck_paiflow_public_config_public CHECK (
    (category='ICON') OR
    (category='COLOR') OR
    (category='TOOL_ICON') OR
    (category='TAG' AND code IN ('BOT_TAGS','FLOW_TAGS','TOOL_TAGS','TOOL_TAGS_V2')) OR
    (category='DEFAULT_SLICE_RULES' AND code IN ('1')) OR
    (category='CUSTOM_SLICE_RULES' AND code IN ('1')) OR
    (category='DEFAULT_SLICE_RULES_CBG' AND code IN ('1')) OR
    (category='CUSTOM_SLICE_RULES_CBG' AND code IN ('1')) OR
    (category='DEFAULT_SLICE_RULES_SPARK' AND code IN ('1')) OR
    (category='CUSTOM_SLICE_RULES_SPARK' AND code IN ('1')) OR
    (category='DEFAULT_SLICE_RULES_AIUI' AND code IN ('1')) OR
    (category='CUSTOM_SLICE_RULES_AIUI' AND code IN ('1')) OR
    (category='CUSTOM_SLICE_SEPERATORS_AIUI' AND code IN ('1')) OR
    (category='CUSTOM_SLICE_SEPERATORS_CBG' AND code IN ('1')) OR
    (category='CUSTOM_SLICE_SEPERATORS_SPARK' AND code IN ('1')) OR
    (category='DB_TABLE_TEMPLATE' AND code IN ('TB')) OR
    (category='DB_TABLE_RESERVED_KEYWORD' AND code IN ('reserved_keyword')) OR
    (category='TEMPLATE' AND code IN ('node')) OR
    (category='SPARK_PRO_QR_CODE' AND code IN ('qr','qr_feishu')) OR
    (category='WORKFLOW' AND code IN ('python-dependency')) OR
    (category='WORKFLOW_CATEGORY')
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

